import numpy as np
f=open('answer.xyz').read().splitlines(); A=[]
for s in f[2:]:
 t=s.split();A.append((t[0],np.array(list(map(float,t[1:4])))))
pc=list(range(52,104)); core=[i for i in range(28) if A[i][0]!='H'];pip=[i for i in range(28,44) if A[i][0]!='H'];otf=list(range(44,52));
P=A[52][1]; O=A[44][1]; S=A[45][1]; axis=S-O;axis/=np.linalg.norm(axis)
def rotmat(axis,th):
 x,y,z=axis;K=np.array([[0,-z,y],[z,0,-x],[-y,x,0]])
 return np.eye(3)+np.sin(th)*K+(1-np.cos(th))*K@K

def eldist(e1,e2):
 # threshold for van der Waals contacts
 if e1=='F' or e2=='F':return 3.05
 if e1 in ('O','N') or e2 in ('O','N'):return 3.0
 return 3.25
best=[]
for dpc in range(0,360,10):
 Rz=rotmat(np.array([0.,0.,1.]),np.deg2rad(dpc))
 ppos={i:P+Rz@(A[i][1]-P) for i in pc}
 for dotf in range(0,360,10):
  Rt=rotmat(axis,np.deg2rad(dotf)); opos={i:A[i][1].copy() for i in range(44,52)}
  for i in range(46,52):opos[i]=O+Rt@(A[i][1]-O)
  score=0; mnd=10; pair=None
  # Intercomponent contacts
  for i in pc:
   if A[i][0]=='H': continue
   for grp in (core,pip,otf):
    for j in grp:
     p1=ppos[i]; p2=opos[j] if j in opos else A[j][1]
     d=np.linalg.norm(p1-p2); cutoff=eldist(A[i][0],A[j][0]);
     pen=max(0,cutoff-d); score+=pen*pen
     if d<mnd:mnd=d;pair=(i,j)
  best.append((score,mnd,dpc,dotf,pair))
