# compare trifl. side sign with scan
import numpy as np
f=open('answer.xyz').read().splitlines();A=[]
for s in f[2:]:
 t=s.split(); A.append((t[0],np.array(list(map(float,t[1:4])))))
PC=range(52,104); core=[i for i in range(28) if A[i][0]!='H'];pip=[i for i in range(28,44) if A[i][0]!='H']; P=A[52][1]
def rotmat(axis,th):
 axis=axis/np.linalg.norm(axis);x,y,z=axis;K=np.array([[0,-z,y],[z,0,-x],[-y,x,0]]);return np.eye(3)+np.sin(th)*K+(1-np.cos(th))*K@K
for sign in [-1,1]:
 # reflect whole triflate in y if side +
 T={i:A[i][1].copy() for i in range(44,52)}
 if sign==1:
  for i in T:T[i][1]*=-1
 O=T[44];S=T[45];axis=S-O
 best=(1e9,None)
 for dp in range(0,360,5):
  Rz=rotmat(np.array([0.,0.,1.]),np.deg2rad(dp)); pp={i:P+Rz@(A[i][1]-P) for i in PC}
  for dt in range(0,360,10):
   Rt=rotmat(axis,np.deg2rad(dt)); tt={i:T[i].copy() for i in T}
   for i in range(46,52):tt[i]=O+Rt@(T[i]-O)
   score=0;mn=10;pair=None
   for i in PC:
    if A[i][0]=='H':continue
    for grp in [core,pip,range(44,52)]:
     for j in grp:
      if j in T:p2=tt[j]
      else:p2=A[j][1]
      e1,e2=A[i][0],A[j][0]
      cut=3.05 if ('F'in (e1,e2)) else (3.0 if ('O'in (e1,e2) or 'N'in (e1,e2)) else 3.25)
      d=np.linalg.norm(pp[i]-p2);score+=max(0,cut-d)**2
      if d<mn:mn=d;pair=(i,j)
   if score<best[0]:best=(score,(mn,dp,dt,pair))
 print('sign',sign,best)
